L=[]
def l(id,stmt,aff,ev,origin="author_stated",eff=None):
    d={"id":id,"statement":stmt,"affects_claims":aff,"origin":origin,"evidence":ev}
    if eff: d["effect_on_interpretation"]=eff
    L.append(d)
l("L001","All BEIR datasets are English, because multilingual retrieval datasets are scarce.",["C020","C043"],["E110"],eff="Findings say nothing about other languages or cross-lingual retrieval.")
l("L002","Most tasks have documents of at most a few hundred words; retrieving longer documents would need a fundamentally different set-up because transformers often have a 512 word-piece limit.",["C020","C043"],["E111"],eff="Rankings may differ for long-document retrieval.")
l("L003","BEIR covers pure text search; real applications also use signals such as PageRank, recency, authority scores or click-through rates, which are hard to integrate.",["C020"],["E112"],eff="Text-only rankings may not carry over to multi-signal search.")
l("L004","Only datasets with one or two text fields are included; multi-field retrieval is not covered.",["C020"],["E113"],eff="Results do not speak to retrieval over many fields.")
l("L005","BEIR evaluates models built to work across tasks; task-specific models can easily beat generic ones and are not what it measures.",["C043"],["E114"],eff="The ranking of systems is a ranking of general-purpose systems.")
l("L006","No benchmark is perfect and has its limitations (the authors' broad statement).",["C043"],["E115"],eff="The central finding holds for this benchmark and these systems, not for retrieval in general.")
l("L007","No error bars or seed variance are reported, because the systems are existing pre-trained checkpoints that often come without training code and re-training is not feasible.",["C030","C031","C032","C033","C034","C035","C036","C037","C038","C039","C043","C044"],["E116"],eff="Differences of a few points between systems cannot be checked against run-to-run variation.")
l("L008","The total amount of compute used is not reported (only the CPU and GPU types).",["C040","C049"],["E117"],eff="Cost is described by latency and index size only.")
l("L009","Offensive content and personally identifiable information were not checked in the more than 50 million documents, because removing content would alter the datasets.",["C020"],["E118"],eff="Datasets are used as released.")
l("L010","Potential negative societal impacts of the work are not discussed.",["C020"],["E119"],eff="No societal analysis accompanies the benchmark.")
l("L011","Even with many systems contributing to the TREC-COVID annotation pool, the pool remains biased towards lexical approaches, which gives non-lexical approaches an unfair disadvantage; fair comparison needs less biased datasets.",["C036","C041","C042","C043","C052"],["E120"],eff="Scores of dense and other non-lexical systems on pooled datasets may understate them, so the BM25 comparison is tilted in BM25's favour to an unmeasured degree on most datasets.")
l("L012","The difference between TAS-B and ANCE is difficult to attribute, because they differ in backbone (DistilBERT vs RoBERTa-base), loss function and hard-negative mining.",["C037","C048"],["E121"],eff="The length-preference explanation rests on a separate controlled experiment.")
l("L013","The maintainers do not vouch for the quality or fairness of the datasets and do not claim that users hold a licence for them; four datasets report no licence.",["C020"],["E122","E049"],eff="Users must check licences and dataset quality themselves.")
l("L101","The annotation-bias study covers one dataset (TREC-COVID) and the nDCG@10 changes concern its top-10 holes; how far lexical bias affects the other 17 datasets is not measured.",["C041","C042","C052"],["E103","E101"],origin="writer_derived",eff="The size of the effect elsewhere is unknown; the TREC-COVID result is an existence demonstration for one pool.")
l("L102","Latency and index size were estimated on one 1M-document DBPedia sample and one CPU/GPU pair.",["C040","C049"],["E090"],origin="writer_derived",eff="Absolute numbers will differ on other hardware, corpus sizes and implementations; only the broad ordering is supported.")
l("L103","Systems differ in several respects at once (training data, backbone, first-stage retrieval): DPR is trained on other data than the MS MARCO systems, and BM25+CE reranks the BM25 top-100.",["C032","C033","C036","C045"],["E023","E025","E026","E030"],origin="writer_derived",eff="Differences between systems cannot be assigned to architecture family alone.")
l("L104","The Table 2 last row averages heterogeneous datasets into one relative number whose computation is not defined; a later study cited by the README (Kamalloo et al., 2024) lists comparisons that reduce heterogeneous scores to a single average as a shortcoming of BEIR comparisons.",["C031"],["E052","E140"],origin="writer_derived",eff="Average percentages are a rough summary; per-dataset scores carry the evidence.")
l("L105","The text's count of datasets where docT5query scores above BM25 (11) differs from the count obtainable from the reconstructed Table 2 (12); the text count is used.",["C034"],["E073","E074"],origin="writer_derived",eff="The exact count for docT5query is uncertain by one dataset.")
l("L106","Several datasets have few test queries (TREC-COVID 50, Touche-2020 49, TREC-NEWS 57, Signal-1M (RT) 97), and per-dataset differences of a few points are reported without intervals.",["C032","C033","C036","C043"],["E005"],origin="writer_derived",eff="Small per-dataset differences (for example ArguAna 0.311 vs 0.315) should not be read as reliable orderings.")
l("L107","SPARTA was re-implemented by the authors and GenQ was capped at 100K documents per dataset, so these two entries may differ from the original or uncapped systems.",["C035","C039"],["E021","E028"],origin="writer_derived",eff="Conclusions about these two systems are conclusions about these implementations.")
l("L108","The missing TREC-COVID judgements were added by the paper's own authors (blind to system), not by independent assessors.",["C042","C052"],["E101","E135"],origin="writer_derived",eff="The improved scores rest on the authors' relevance judgements.")

# cross-link limitations into claims
for cl in C:
    cl.setdefault("limitations",[])
for lim in L:
    for cid in lim["affects_claims"]:
        cc=next(x for x in C if x["id"]==cid)
        if lim["id"] not in cc["limitations"]: cc["limitations"].append(lim["id"])
for cl in C:
    if not cl["limitations"]: del cl["limitations"]
neg=[{"evidence":e,"decision":"reported_main","reason":"bears directly on the central claim; reported in Results"} for e in ["E071","E075","E077","E084","E088"]]
json.dump({"claims":C,"limitations":L,"negative_result_decisions":neg},open("claims/claim_evidence_map.json","w",encoding="utf-8"),indent=1,ensure_ascii=False)
json.dump({"candidates":[{"id":x["id"],"statement":x["statement"],"claim_type":x["claim_type"],"evidence":x["evidence"],"origin":x["origin"]} for x in C]},open("claims/claim_candidates.json","w",encoding="utf-8"),indent=1,ensure_ascii=False)
print(len(C),len(L))
